    # ── Bad-bot blocker at edge (nginx-ultimate-bad-bot-blocker) ─────────────
    # Http-scope map/geo blocklists (bad UAs, referrers, IPs) + rate-limit zones.
    include /etc/nginx/bot-blocker/conf.d/globalblacklist.conf;
    # WIMS-specific zone definitions (e.g. the `flood` zone for ddos.conf).
    include /etc/nginx/bot-blocker/conf.d/wims-botblocker-settings.conf;
    # ---------------------------------------------------------------------------

    # CI-only HTTP server — no TLS, no certs required.
    # Used by GitHub Actions security-scan job via docker-compose.ci.yml.
    # Local dev using docker-compose.override.yml gets the HTTPS nginx.local.conf
    # (requires self-signed certs generated in .ssl/).
    # Production uses nginx.conf with real Let's Encrypt certs via docker-compose.prod.yml.
    server {
        listen 80;
        listen [::]:80;
        server_name localhost wimsbfp.tech;

        add_header X-Content-Type-Options nosniff always;
        add_header X-Frame-Options SAMEORIGIN always;
        add_header Referrer-Policy no-referrer always;
        add_header Permissions-Policy "camera=(), microphone=(), geolocation=(self)" always;
        add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: https://*.tile.openstreetmap.org https://unpkg.com; connect-src 'self' https://*.tile.openstreetmap.org https://wimsbfp.tech; font-src 'self' https://fonts.gstatic.com; worker-src 'self' https://www.gstatic.com; frame-src 'self'; frame-ancestors 'self'" always;
        add_header Cross-Origin-Embedder-Policy "unsafe-none" always;

        # Edge bot-blocker (nginx-ultimate-bad-bot-blocker)
        include /etc/nginx/bot-blocker/bots.d/blockbots.conf;
        include /etc/nginx/bot-blocker/bots.d/ddos.conf;

        location = /health {
            access_log off;
            default_type application/json;
            return 200 '{"status":"ok","via":"nginx-gateway"}\n';
        }

        location /api/auth/ {
            proxy_pass http://frontend:3000;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_pass_request_headers on;
        }

        location /api/v1/public/ {
            limit_req  zone=public_api burst=5 nodelay;
            limit_conn addr 10;

            proxy_pass http://backend_servers;
            proxy_set_header Host $host;
            # Use the pre-real-IP-module socket address so the backend rate
            # limiter cannot be bypassed by a spoofed X-Forwarded-For header.
            proxy_set_header X-Real-IP $realip_remote_addr;
            proxy_set_header X-Forwarded-For $realip_remote_addr;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 60s;
            proxy_send_timeout 60s;
            proxy_cookie_domain nginx-gateway $host;
            add_header Access-Control-Allow-Origin $scheme://$host always;
            add_header Access-Control-Allow-Credentials true always;
            add_header Access-Control-Allow-Methods 'GET, POST, PUT, DELETE, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Authorization, Content-Type, Cookie' always;
            add_header Access-Control-Expose-Headers "Retry-After" always;

            if ($request_method = 'OPTIONS') {
